<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Webkul\CMS\Models\Page;
use Webkul\CMS\Models\PageTranslation;
use Webkul\Core\Models\Channel;

class ShamimBlogSeeder extends Seeder
{
    public function run(): void
    {
        $articles = [
            ['entekhab-jabe-ghazaye-garm', 'برای غذای گرم چه جعبه‌ای مناسب‌تر است؟', 'راهنمای انتخاب بسته‌بندی مناسب برای حفظ دما، بافت و کیفیت غذای گرم در مسیر ارسال.', 'جعبه غذای گرم، بسته بندی غذا، جعبه فست فود', 'pack-chicken.png', '<h2>سه معیار اصلی برای غذای گرم</h2><p>جعبه مناسب باید گرما را حفظ کند، بخار اضافی را بیرون بدهد و در تماس با روغن تغییر شکل ندهد. بسته‌بندی کاملاً بسته برای غذای ترد مناسب نیست؛ چون بخار داخل آن جمع می‌شود و بافت غذا را نرم می‌کند.</p><h2>جنس جعبه را بر اساس نوع غذا انتخاب کنید</h2><ul><li><strong>سوخاری و سیب‌زمینی:</strong> جعبه دارای دریچه تهویه و کاغذ مقاوم به چربی.</li><li><strong>برگر و ساندویچ:</strong> مقوای Food Grade با ساختار محکم و ابعاد متناسب.</li><li><strong>غذاهای سس‌دار:</strong> پوشش داخلی مقاوم به رطوبت و قفل مطمئن.</li></ul><h2>اندازه دقیق، کیفیت بیشتر</h2><p>فضای خالی زیاد باعث حرکت محصول و افت ظاهر آن می‌شود. پیش از سفارش عمده، ابعاد محصول نهایی را اندازه بگیرید.</p>'],
            ['chap-branding-bastebandi', 'چاپ اختصاصی و برندینگ روی بسته‌بندی غذا', 'چطور با رنگ، لوگو و پیام درست، جعبه غذا را به یک رسانه تبلیغاتی مؤثر تبدیل کنیم؟', 'چاپ جعبه غذا، چاپ اختصاصی، برندینگ رستوران', 'pack-burger.png', '<h2>جعبه، بخشی از تجربه برند است</h2><p>مشتری پیش از دیدن غذا، بسته‌بندی را می‌بیند. لوگوی خوانا، رنگ ثابت و پیام کوتاه حس حرفه‌ای بودن را منتقل می‌کند.</p><h2>چه چیزی روی جعبه چاپ کنیم؟</h2><ul><li>لوگو و نام برند در نقطه‌ای واضح</li><li>آدرس شبکه اجتماعی یا QR Code</li><li>پیام کوتاه درباره کیفیت مواد اولیه</li><li>اطلاعات تماس و سفارش مجدد</li></ul><h2>سادگی بهتر دیده می‌شود</h2><p>یک رنگ اصلی، یک رنگ مکمل و فضای سفید کافی معمولاً نتیجه‌ای حرفه‌ای‌تر از طرح شلوغ دارد.</p>'],
            ['bastebandi-foroush-dobare', 'بسته‌بندی چگونه فروش دوباره را بیشتر می‌کند؟', 'بسته‌بندی سالم، خوش‌دست و به‌یادماندنی یکی از ساده‌ترین راه‌های افزایش رضایت و سفارش مجدد است.', 'افزایش فروش رستوران، بسته بندی حرفه ای، تجربه مشتری', 'pack-sandwich.png', '<h2>کیفیت غذا باید تا لحظه تحویل حفظ شود</h2><p>نشتی سس، له شدن جعبه یا سرد شدن سریع غذا مستقیماً روی قضاوت مشتری اثر می‌گذارد. بسته‌بندی مناسب، آخرین مرحله کنترل کیفیت شماست.</p><h2>باز کردن آسان و حمل مطمئن</h2><p>قفل مناسب، چیدمان درست و امکان حمل آسان، تجربه مشتری را بهتر می‌کند و احتمال سفارش دوباره را بالا می‌برد.</p><h2>راه بازگشت مشتری را کوتاه کنید</h2><p>شماره تماس، آدرس سایت یا QR Code سفارش را روی جعبه قرار دهید. یک پیام دوستانه کوتاه نیز جعبه را به ابزار وفادارسازی تبدیل می‌کند.</p>'],
            ['rahnamaye-entekhab-jabe-fastfood', 'راهنمای انتخاب جعبه سوخاری، برگر و ساندویچ', 'مقایسه کاربردی انواع جعبه فست‌فود برای انتخاب ابعاد، جنس و ساختار مناسب هر محصول.', 'جعبه سوخاری، جعبه برگر، جعبه ساندویچ، کاغذ کرافت', 'pack-fries.png', '<h2>جعبه سوخاری</h2><p>برای مرغ و قطعات سوخاری، استحکام کف و گردش هوا اهمیت بیشتری دارد. جعبه باید در برابر چربی مقاوم باشد.</p><h2>جعبه برگر و ساندویچ</h2><p>ابعاد نزدیک به محصول، مانع جابه‌جایی محتویات می‌شود. برای برگرهای حجیم، ارتفاع درب و مقاومت گوشه‌ها را جدی بگیرید.</p><h2>جعبه سیب‌زمینی و کاغذ کرافت</h2><p>ساختار باز جعبه سیب‌زمینی به خروج بخار کمک می‌کند. کاغذ کرافت نیز ظاهری طبیعی و گرم دارد.</p><h2>پیش از تولید عمده نمونه بگیرید</h2><p>نمونه را با غذای واقعی و در مدت زمان معمول ارسال آزمایش کنید.</p>'],
        ];

        $channelIds = Channel::query()->pluck('id');

        foreach ($articles as [$slug, $title, $description, $keywords, $image, $body]) {
            $translation = PageTranslation::query()->where('url_key', $slug)->first();
            $page = $translation ? Page::query()->findOrFail($translation->cms_page_id) : Page::query()->create(['layout' => 'default']);

            PageTranslation::query()->updateOrCreate(
                ['cms_page_id' => $page->id, 'locale' => 'fa'],
                ['page_title' => $title, 'url_key' => $slug, 'html_content' => '<img src="/themes/shop/shamim-pack/images/'.$image.'" alt="'.$title.'">'.$body, 'meta_title' => $title.' | جعبه فروش', 'meta_description' => $description, 'meta_keywords' => $keywords]
            );

            $page->channels()->syncWithoutDetaching($channelIds);
        }
    }
}
